function restoreHold(){clearInterval(holdInterval);holdUpdate();if(readHold())holdInterval=setInterval(holdUpdate,500);}
function setHoldMinutes(minutes){const value={profile:state.selected,until:Date.now()+minutes*60000,minutes};storage.set(holdKey(),JSON.stringify(value));document.querySelectorAll('[data-hold-minutes]').forEach(b=>b.classList.toggle('active',Number(b.dataset.holdMinutes)===minutes));restoreHold();}
startHold=function(){if(!readHold())setHoldMinutes(5);else restoreHold();$('hold-description').textContent='A pause, not a promise: urges often ease within a few minutes, but timing varies. Sip water, change rooms, or message the crew. You choose what happens next.';showDialog('hold-dialog');renderHoldPill();};
closeDialog=function(id){$(id).close();if(id==='hold-dialog')renderHoldPill();};
$('hold-dialog').addEventListener('close',restoreHold);$('hold-dialog').addEventListener('cancel',()=>setTimeout(restoreHold,0));
$('hold-live-pill').addEventListener('click',startHold);$('hold-more').addEventListener('click',()=>{setHoldMinutes(5);showToast('Five more minutes. No win recorded automatically.');});$('hold-dismiss').addEventListener('click',()=>{clearHold();closeDialog('hold-dialog');showToast('Timer ended without logging an outcome.');});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)restoreHold();});
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.holdMinutes){setHoldMinutes(Number(b.dataset.holdMinutes));return;}const action=b.dataset.v2;if(!action)return;
 if(action==='ranks')showDialog('ranks-dialog');else if(action==='fact'){lastFactOffset++;if(me())renderFacts(me());}else if(action==='thread'){state.thread=b.dataset.post;showDialog('thread-dialog');renderSocial();}else if(action==='vote')await v2Mutation(()=>state.repo.social('vote',state.selected,b.dataset.post));else if(action==='delete-post')await v2Mutation(()=>state.repo.social('delete',state.selected,b.dataset.post));else if(action==='duel')openDuel(b.dataset.opponent);else if(action==='challenge-action'){const ok=await v2Mutation(()=>state.repo.challenge(b.dataset.duelAction,state.selected,b.dataset.duel,b.dataset.winner||null));if(ok)showToast(b.dataset.duelAction==='claim'?'Result proposed. The other participant needs to confirm.':'Duel updated.');}else if(action==='roamer'){const off=storage.get('kme-roamer')!=='off';storage.set('kme-roamer',off?'off':'on');b.textContent=off?'Screen goblin: off':'Screen goblin: on';if(off)document.querySelector('.goblin-roamer')?.remove();else roam();}else if(action==='refresh-world')await refreshWorld();
});
$('message-form').addEventListener('submit',async e=>{e.preventDefault();const body=$('message-body').value.trim();if(!body)return;const ok=await v2Mutation(()=>state.repo.social('post',state.selected,null,body));if(ok){$('message-body').value='';showToast('Memo posted. The crew has been informed.');}});
$('comment-form').addEventListener('submit',async e=>{e.preventDefault();const body=$('comment-body').value.trim();if(!body||!state.thread)return;const ok=await v2Mutation(()=>state.repo.social('comment',state.selected,state.thread,body));if(ok)$('comment-body').value='';});
$('duel-form').addEventListener('submit',async e=>{e.preventDefault();const opponent=$('duel-opponent').value;if(!opponent)return;const ok=await v2Mutation(()=>state.repo.challenge('create',state.selected,opponent));if(ok){closeDialog('duel-dialog');navigate('arena');showToast('Duel invitation posted. Your friend accepts from their phone.');}});
function roam(){clearTimeout(roamerTimer);if(!document.hidden&&!$('app').hidden&&storage.get('kme-roamer')!=='off'&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.querySelector('.goblin-roamer')){const goblin=document.createElement('div');goblin.className='goblin-roamer';goblin.setAttribute('aria-hidden','true');goblin.innerHTML=avatarSvg('goblin');document.body.append(goblin);goblin.addEventListener('animationend',e=>{if(e.target===goblin)goblin.remove();});setTimeout(()=>goblin.remove(),11000);}roamerTimer=setTimeout(roam,45000+Math.random()*60000);}
roamerTimer=setTimeout(roam,18000);$('roamer-toggle').textContent=storage.get('kme-roamer')==='off'?'Screen goblin: off':'Screen goblin: on';
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.page==='arena'&&!document.querySelector('dialog[open]')){window.KMEArena?.destroy();arenaProfile=null;mountArena();}});


